import sys
import json
import os
import re

def parse_date(val):
    if val is None:
        return None
    s = str(val).strip()
    if not s or s.upper() in ('N/A', 'NONE', 'NULL', ''):
        return None
    if len(s) == 8 and s.isdigit():
        return f"{s[:4]}-{s[4:6]}-{s[6:8]}"
    if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
        return s
    return s

def main():
    if len(sys.argv) < 3:
        return

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, 'r', encoding='utf-8') as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports.json
    fda_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall_number = {}
    if os.path.exists(fda_file):
        with open(fda_file, 'r', encoding='utf-8') as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                rec_num = item.get("recall_number")
                if rec_num:
                    records_by_recall_number.setdefault(rec_num.strip(), []).append(item)

    fact_field_map = {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date", True),
        "classification date": ("fda_enforcement_reports", "center_classification_date", True),
        "termination date": ("fda_enforcement_reports", "termination_date", True),
    }

    output = {}

    pairs = manifest.get("pairs", [])
    facts_schema = manifest.get("facts", {})

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity_id = pair.split("::", 1)
        entity_id_clean = entity_id.strip()

        entity_facts = facts_schema.get(rule_id, [])
        pair_result = {}

        matching_records = records_by_recall_number.get(entity_id_clean, [])

        for fact_name in entity_facts:
            if fact_name not in fact_field_map:
                pair_result[fact_name] = "ABSENT"
                continue

            doc_name, field_name, is_date = fact_field_map[fact_name]

            if not matching_records:
                pair_result[fact_name] = "ABSENT"
                continue

            values = set()
            for record in matching_records:
                raw_val = record.get(field_name)
                val = parse_date(raw_val) if is_date else (str(raw_val).strip() if raw_val is not None else None)
                if val:
                    values.add(val)

            if not values:
                pair_result[fact_name] = "ABSENT"
            elif len(values) > 1:
                pair_result[fact_name] = "CONFLICT"
            else:
                pair_result[fact_name] = [next(iter(values)), doc_name]

        output[pair] = pair_result

    print(json.dumps(output, indent=2))

if __name__ == '__main__':
    main()

