import sys
import json
import os

def format_date(val):
    if not val or not isinstance(val, str):
        return None
    val = val.strip()
    if not val or val.upper() in ("N/A", "NONE", "NULL", "UNKNOWN"):
        return None
    if len(val) == 8 and val.isdigit():
        return f"{val[:4]}-{val[4:6]}-{val[6:]}"
    parts = val.split("-")
    if len(parts) == 3 and len(parts[0]) == 4 and len(parts[1]) == 2 and len(parts[2]) == 2:
        return val
    return val

RULE_FACT_MAP = {
    "fda.classified_30d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "classification date": ("fda_enforcement_reports", "center_classification_date"),
    },
    "fda.terminated_180d": {
        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    }
}

FACT_FIELD_MAP = {
    "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
    "classification date": ("fda_enforcement_reports", "center_classification_date"),
    "termination date": ("fda_enforcement_reports", "termination_date"),
}

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports.json
    reports_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall_number = {}

    if os.path.exists(reports_file):
        with open(reports_file, "r", encoding="utf-8") as f:
            raw_data = json.load(f)
            if isinstance(raw_data, dict) and "results" in raw_data:
                items = raw_data["results"]
            elif isinstance(raw_data, list):
                items = raw_data
            else:
                items = []

            for item in items:
                rec_num = item.get("recall_number")
                if rec_num:
                    records_by_recall_number.setdefault(rec_num, []).append(item)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        if "::" in pair:
            rule_id, entity = pair.split("::", 1)
        else:
            rule_id, entity = pair, ""

        rule_facts = facts_spec.get(rule_id, [])
        pair_output = {}

        matching_records = records_by_recall_number.get(entity, [])

        for fact_name in rule_facts:
            mapping = RULE_FACT_MAP.get(rule_id, {}).get(fact_name) or FACT_FIELD_MAP.get(fact_name)
            if not mapping:
                pair_output[fact_name] = "ABSENT"
                continue

            doc_name, field_name = mapping

            values = set()
            for rec in matching_records:
                raw_val = rec.get(field_name)
                formatted = format_date(raw_val)
                if formatted is not None:
                    values.add(formatted)

            if len(values) == 0:
                pair_output[fact_name] = "ABSENT"
            elif len(values) == 1:
                pair_output[fact_name] = [next(iter(values)), doc_name]
            else:
                pair_output[fact_name] = "CONFLICT"

        output[pair] = pair_output

    print(json.dumps(output, indent=2))

if __name__ == "__main__":
    main()

