import json
import os
import re
import sys


def normalize_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.upper() == "N/A":
        return None

    m = re.match(r"^(\d{4})(\d{2})(\d{2})$", val)
    if m:
        return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"

    m = re.match(r"^(\d{4})[-/](\d{2})[-/](\d{2})$", val)
    if m:
        return f"{m.group(1)}-{m.group(2)}-{m.group(3)}"

    return val


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    # Load fda_enforcement_reports
    report_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall_number = {}

    if os.path.exists(report_file):
        with open(report_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    key = str(recall_num).strip()
                    records_by_recall_number.setdefault(key, []).append(item)

    # Field mapping
    fact_to_field = {
        "initiation date": ("recall_initiation_date", "fda_enforcement_reports"),
        "classification date": ("center_classification_date", "fda_enforcement_reports"),
        "termination date": ("termination_date", "fda_enforcement_reports"),
    }

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        entity_key = entity.strip()
        needed_facts = facts_spec.get(rule_id, [])

        pair_result = {}
        matching_records = records_by_recall_number.get(entity_key, [])

        for fact_name in needed_facts:
            mapping = fact_to_field.get(fact_name)
            if not mapping:
                pair_result[fact_name] = "ABSENT"
                continue

            field_name, doc_name = mapping
            values = set()

            for rec in matching_records:
                raw_val = rec.get(field_name)
                norm_val = normalize_date(raw_val)
                if norm_val is not None:
                    values.add(norm_val)

            if len(values) == 0:
                pair_result[fact_name] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact_name] = [list(values)[0], doc_name]
            else:
                pair_result[fact_name] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

