import sys
import json
import os
import re

def parse_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val or val.upper() in ("N/A", "NONE", "NULL"):
        return None
    if re.match(r"^\d{8}$", val):
        return f"{val[:4]}-{val[4:6]}-{val[6:8]}"
