        "initiation date": ("fda_enforcement_reports", "recall_initiation_date"),
        "termination date": ("fda_enforcement_reports", "termination_date"),
    }
}

def load_document(packet_dir, doc_name):
    for ext in (".json", ""):
        path = os.path.join(packet_dir, doc_name + ext)
        if os.path.isfile(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict) and "results" in data:
                return data["results"]
            elif isinstance(data, list):
                return data
            elif isinstance(data, dict):
                return [data]
    return []

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_spec = manifest.get("facts", {})

    loaded_docs = {}

    out = {}

    for pair in pairs:
        if "::" not in pair:
            continue
        rule_id, entity = pair.split("::", 1)
        fact_names = facts_spec.get(rule_id, [])

        rule_mapping = RULE_FIELD_MAP.get(rule_id, {})
        pair_out = {}

        for fact in fact_names:
            if fact not in rule_mapping:
                pair_out[fact] = "ABSENT"
                continue

            doc_name, field_name = rule_mapping[fact]
            if doc_name not in loaded_docs:
                loaded_docs[doc_name] = load_document(packet_dir, doc_name)

            records = loaded_docs[doc_name]
            matching_records = [
                r for r in records
                if isinstance(r, dict) and r.get("recall_number") == entity
            ]

            values = set()
            for r in matching_records:
                raw_val = r.get(field_name)
                formatted = parse_date(raw_val)
                if formatted is not None:
                    values.add(formatted)

            if len(values) == 0:
                pair_out[fact] = "ABSENT"
            elif len(values) == 1:
                val = next(iter(values))
                pair_out[fact] = [val, doc_name]
            else:
                pair_out[fact] = "CONFLICT"

        out[pair] = pair_out

    print(json.dumps(out, indent=2))

if __name__ == "__main__":
    main()

