import json
import os
import sys
from datetime import datetime

FACT_FIELD_MAP = {
    "initiation date": "recall_initiation_date",
    "classification date": "center_classification_date",
    "termination date": "termination_date",
}


def normalize_date(val):
    if val is None:
        return None
    val = str(val).strip()
    if not val:
        return None
    for fmt in ("%Y%m%d", "%Y-%m-%d", "%m/%d/%Y", "%Y/%m/%d"):
        try:
            dt = datetime.strptime(val, fmt)
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            pass
    return val


def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    packet_dir = sys.argv[1]
    manifest_path = sys.argv[2]

    with open(manifest_path, "r", encoding="utf-8") as f:
        manifest = json.load(f)

    pairs = manifest.get("pairs", [])
    facts_by_rule = manifest.get("facts", {})

    enforcement_file = os.path.join(packet_dir, "fda_enforcement_reports.json")
    records_by_recall_number = {}

    if os.path.exists(enforcement_file):
        with open(enforcement_file, "r", encoding="utf-8") as f:
            data = json.load(f)
            results = data.get("results", [])
            for item in results:
                recall_num = item.get("recall_number")
                if recall_num:
                    records_by_recall_number.setdefault(recall_num, []).append(item)

    doc_name = "fda_enforcement_reports"
    output = {}

    for pair in pairs:
        rule_id, entity = pair.split("::", 1)
        needed_facts = facts_by_rule.get(rule_id, [])
        matching_records = records_by_recall_number.get(entity, [])

        pair_result = {}
        for fact in needed_facts:
            field = FACT_FIELD_MAP.get(fact)
            if not field or not matching_records:
                pair_result[fact] = "ABSENT"
                continue

            values = set()
            for rec in matching_records:
                raw_val = rec.get(field)
                norm_val = normalize_date(raw_val)
                if norm_val:
                    values.add(norm_val)

            if len(values) == 0:
                pair_result[fact] = "ABSENT"
            elif len(values) == 1:
                pair_result[fact] = [values.pop(), doc_name]
            else:
                pair_result[fact] = "CONFLICT"

        output[pair] = pair_result

    print(json.dumps(output, indent=2))


if __name__ == "__main__":
    main()

